/**
 * Which CLI command this process runs, sent on each Cursor backend call so
 * the backend can count usage per command. Unset outside the CLI (library
 * use, hosted engines), where requests carry only the user agent.
 */
import { CLI_COMMAND_NAME, packageVersion } from "./distribution.js";
/**
 * Subcommands counted apart, per parent command. Each set names only words
 * that parent's dispatcher accepts, so a free-form positional (an eval id, a
 * URL) never becomes a tag. `eval` takes eval ids in that position. The old
 * names (`secrets`, `images`, `eval status`) still run as aliases, so they
 * stay counted too.
 */
const SUBCOMMANDS = new Map([
    ["bitbucket", new Set(["replay", "events", "forward"])],
    [
        "deployment",
        new Set([
            "list",
            "get",
            "stop",
            "start",
            "kill",
            "unlock",
            "cancel-runs",
            "update",
            "upgrade",
            "rollback",
            "delete",
            "rotate-token",
        ]),
    ],
    ["eval", new Set(["list", "get", "status", "cancel"])],
    ["github", new Set(["forward", "replay", "events", "doctor"])],
    ["gitlab", new Set(["replay", "events", "forward"])],
    ["image", new Set(["push", "list", "delete"])],
    ["images", new Set(["push", "list", "rm"])],
    ["mcp", new Set(["serve", "install", "oauth"])],
    ["pagerduty", new Set(["replay", "events"])],
    ["secret", new Set(["set", "list", "delete"])],
    ["secrets", new Set(["set", "list", "unset"])],
    ["session", new Set(["list", "get", "create"])],
    ["skills", new Set(["install"])],
    ["slack", new Set(["setup", "create", "destroy", "icon", "init", "manifest", "doctor"])],
    ["tool", new Set(["call"])],
]);
const COMMAND_WORD = /^[a-z][a-z-]{0,31}$/;
export const CLI_COMMAND_HEADER = "x-bdk-command";
let invocation;
/**
 * Record the running command. `subcommand` counts only when
 * {@link SUBCOMMANDS} lists it under `command`, so ids and URLs in that
 * position never leave the machine.
 */
export function setCliInvocation(command, subcommand) {
    if (!COMMAND_WORD.test(command)) {
        invocation = undefined;
        return;
    }
    invocation =
        subcommand !== undefined && SUBCOMMANDS.get(command)?.has(subcommand) === true
            ? `${command} ${subcommand}`
            : command;
}
/**
 * Record a command by its registry name, such as `deployment get`. The
 * dispatcher calls this after it resolves the words and any alias, so an
 * old name or a flag before the subcommand counts as the new command.
 */
export function setCliCommand(name) {
    const [command = "", subcommand] = name.split(" ");
    setCliInvocation(command, subcommand);
}
export function cliInvocation() {
    return invocation;
}
/** Headers for one Cursor backend request. */
export function cliRequestHeaders() {
    const headers = {
        "user-agent": `${CLI_COMMAND_NAME}/${packageVersion()} node/${process.versions.node}`,
    };
    if (invocation !== undefined) {
        headers[CLI_COMMAND_HEADER] = invocation;
    }
    return headers;
}
